INSERT INTO `movie` VALUES (1, '星际穿越', 'Interstellar', '克里斯托弗・诺兰', '克里斯托弗・诺兰', '马修·麦康纳', '科幻', '美国', '英语', '2014-11-05', 169, '《星际穿越》是 2014 年美英联合制作的科幻电影，由克里斯托弗・诺兰执导。影片基于物理学家基普・索恩的黑洞理论改编，讲述了在地球面临生态危机时，前 NASA 宇航员库珀带领探险队穿越虫洞，前往另一个星系寻找新家园的冒险历程。他们在不同星球经历了种种挑战，库珀还进入五维空间，通过引力将黑洞数据传递给女儿墨菲，最终人类在墨菲的帮助下离开地球，库珀则前往埃德蒙斯星球寻找同伴艾米莉亚。', 9.2, 2000000, 726000.00, 1, '2025-05-28 11:34:46', 'picture\\\\星际穿越.jpg');
INSERT INTO `movie` VALUES (2, '霸王别姬', '霸王别姬', '陈凯歌', '李碧华', '张国荣', '爱情', '中国', '中文', '1993-01-01', 171, '《霸王别姬》是1993年由陈凯歌执导的经典华语电影，改编自李碧华同名小说。影片以京剧艺人程蝶衣（张国荣 饰）和段小楼（张丰毅 饰）的人生轨迹为主线，横跨民国、抗战、文革等多个历史时期，展现了个体命运与时代洪流的激烈碰撞。\r\n程蝶衣自幼被母亲送入戏班，因性别认知错乱（儿时被迫唱 “我本是女娇娥”）而深陷角色，将京剧视为生命信仰，对段小楼的 “从一而终” 更成为其情感与艺术的双重执念。段小楼则在现实压力下逐渐妥协，从 “霸王” 沦为随波逐流的普通人。两人因师妹菊仙（巩俐 饰）的介入产生裂痕，文革中互相揭发的背叛戏码更是将人性的脆弱与时代的荒诞推向高潮。\r\n影片以京剧为魂，用细腻的镜头语言和深刻的悲剧内核，探讨了艺术与现实、性别与身份、忠诚与背叛的复杂命题。张国荣的 “不疯魔不成活” 的极致演绎成为影史经典，该片更斩获戛纳金棕榈奖等多项国际大奖，被誉为 “华语电影美学的巅峰”。', 9.4, 1455555, 500000.00, 1, '2025-05-28 14:27:57', 'picture\\\\霸王别姬.jpg');
INSERT INTO `movie` VALUES (3, '阿甘正传', 'Forrest Gump', '罗伯特·泽米斯基', '艾瑞克·罗斯', '汤姆·汉克斯', '喜剧', '美国', '英语', '1994-07-06', 142, '\r\n《阿甘正传》是1994年上映的美国经典励志电影，由罗伯特·泽米吉斯执导，汤姆·汉克斯主演。影片通过智商略低但心地单纯的主人公阿甘（汤姆·汉克斯 饰）的视角，串联起美国20世纪50至80年代的重要历史事件。他从小因腿疾戴 braces 却练成跑步健将，加入橄榄球队、参与越战并获勋章，成为乒乓球外交参与者，还因捕虾成为富翁。尽管一生经历爱情波折（如恋人珍妮的流浪与归来）、好友布巴战死等遗憾，却始终以善良和执着拥抱生活。影片用温情笔触探讨命运与选择，那句“生活就像一盒巧克力，你永远不知道下一颗是什么味道”成为经典台词，传递出对纯真心灵的赞美与生命韧性的礼赞。', 9.5, 1507000, 487303.00, 1, '2025-05-28 14:30:27', 'picture\\\\阿甘正传.jpg');
INSERT INTO `movie` VALUES (4, '泰坦尼克号', 'Titanic', '詹姆斯·卡梅隆', '詹姆斯·卡梅隆', '莱昂纳多·迪卡普里奥', '爱情', '美国', '英语', '1997-12-19', 194, '1912 年 4 月 10 日，号称 “世界工业史上的奇迹” 的豪华游轮泰坦尼克号开始首航。贵族女孩罗丝与母亲及未婚夫卡尔坐上了头等舱，画家杰克偶然得到一张下等舱船票也登上此游轮。罗丝厌倦上流社会生活，准备投海自尽时被杰克救下，两人感情升温。然而，4 月 14 日晚泰坦尼克号撞上冰山，即将沉没，杰克被卡尔陷害困在下层船舱，罗丝赶来救出了他。之后，杰克劝说罗丝上救生艇，但罗丝最终不忍心放弃杰克，又回到船上。随着船缓缓下沉，杰克带着罗丝跑到船尾，爬上栏杆，直到船只完全沉没，杰克将罗丝推上一块浮在海面的木板，自己则留在冰冷海水中，最终杰克冻死，罗丝幸运生还。', 9.4, 1339000, 153009.00, 1, '2025-05-28 14:34:19', 'picture\\\\泰坦尼克号.jpg');
INSERT INTO `movie` VALUES (5, '千与千寻', '千と千尋の神隠し', '宫崎骏', '宫崎骏', '入野自由', '动画', '日本', '日语', '2001-07-20', 125, '《千与千寻》是 2001 年宫崎骏执导、吉卜力工作室制作的动画电影。影片讲述 10 岁少女千寻随父母误入神灵世界，父母因贪吃变成猪，她被迫在魔女汤婆婆的浴场打工求生的故事。\r\n在这个光怪陆离的世界里，千寻结识了神秘少年白龙、无脸男等角色，历经锅炉房煤灰精灵的帮助、河神污物清理等考验，逐渐学会勇敢与独立。她凭借纯真善良打破咒语，不仅拯救了父母，还帮助白龙找回本名。\r\n影片以细腻画风构建奇幻世界观，融入日本神道教元素与环保主题，如河神身上的人类垃圾隐喻生态危机。千寻的成长历程充满哲思，那句 “千万不要忘记自己的名字” 成为核心隐喻，传递着对初心与勇气的赞美。该片获奥斯卡最佳动画长片奖，是全球动画史上的经典之作。', 9.4, 1208000, 151603.00, 1, '2025-05-28 14:38:58', 'picture\\\\千与千寻.jpg');
INSERT INTO `movie` VALUES (6, '肖申克的救赎', 'The Shawshank Redemption', '弗兰克·德拉邦特', '弗兰克·德拉邦特', '蒂姆·罗宾斯', '剧情', '美国', '英语', '1994-09-23', 142, '《肖申克的救赎》是 1994 年弗兰克・德拉邦特执导的美国剧情片，改编自斯蒂芬・金小说。银行家安迪（蒂姆・罗宾斯 饰）因被诬陷杀妻及情人入狱，在肖申克监狱受尽折磨，却始终心怀希望。他利用金融知识为典狱长洗钱，同时暗中用小鹤嘴锄挖通墙壁。\r\n狱中，他与黑人瑞德（摩根・弗里曼 饰）结为挚友，以音乐抚慰狱友心灵，还为监狱扩建图书馆。最终，安迪在一个雨夜通过排污管道逃出，揭露典狱长罪行。瑞德获释后，循着安迪留下的线索找到海边，两人在墨西哥重逢。\r\n影片以 “希望” 为核，用细腻叙事展现体制化对人的侵蚀与人性的坚韧。“有些鸟儿是关不住的，因为它们的羽毛太鲜亮” 成为经典隐喻，曾获 7 项奥斯卡提名，虽未获奖却常年稳居 IMDb 榜首，被视为影史最伟大的励志片之一。', 9.7, 2400000, 206301.00, 1, '2025-06-03 18:51:09', 'picture\\\\肖申克的救赎.jpg');
INSERT INTO `movie` VALUES (7, '盗梦空间', 'Inception', '克里斯托·弗罗兰', '克里斯托·弗罗兰', '莱昂纳多·迪卡普里奥', '科幻', '英国', '英语', '2010-09-01', 148, '\r\n《盗梦空间》是2010年克里斯托弗·诺兰执导的科幻悬疑电影，由莱昂纳多·迪卡普里奥主演。影片讲述盗梦师柯布（莱昂纳多 饰）带领团队通过潜入梦境窃取商业机密的故事，其核心设定是“梦中嵌套多层梦境”的复杂结构，每层梦境的时间流速不同（如“柯布旋转陀螺”成为贯穿全片的“图腾”，用于区分现实与梦境）。  \r\n\r\n柯布因妻子梅尔（玛丽昂·歌迪亚 饰）因沉迷梦境自杀而背负心理阴影，在接到最后一单“植入想法”的任务时，试图通过完成任务回到孩子身边。团队深入目标人物齐藤（渡边谦 饰）的潜意识，从第一层暴雨追车、第二层酒店失重格斗到第三层雪山堡垒，甚至进入潜意识边缘“迷失域”。过程中梅尔的幻影不断干扰，柯布最终直面内心愧疚，完成植入并疑似回到现实。  \r\n\r\n影片以精密的叙事结构、震撼的视觉效果（如折叠城市、无重力打斗）和哲学化的主题（现实与虚幻的边界、记忆与执念的困局）引发全球热议。诺兰通过“陀螺是否停止转动”的开放式结局，让观众持续探讨“什么是真实”，该片斩获4项奥斯卡奖，成为科幻电影中兼具商业与艺术深度的标杆之作。', 9.4, 1700000, 600907.00, 1, '2025-06-03 18:55:57', 'picture\\\\盗梦空间.jpg');
INSERT INTO `movie` VALUES (8, '卧虎藏龙', '卧虎藏龙', '李安', '王蕙玲', '周润发', '动作', '中国', '中文', '2000-07-08', 120, '《卧虎藏龙》是 2000 年由李安执导的武侠电影，改编自王度庐同名小说，融合东方武侠意境与西方哲学思考，被誉为武侠电影的革新之作。\r\n影片以清朝末年为背景，江湖高手李慕白（周润发 饰）决定退隐江湖，将随身宝剑 “青冥剑” 托付给红颜知己俞秀莲（杨紫琼 饰）送往京城。不料宝剑中途被盗，引出飞扬跋扈的 “玉娇龙”（章子怡 饰）—— 她出身贵族却向往江湖自由，偷剑后与李慕白、俞秀莲等人展开多场经典对决：竹林间衣袂翻飞的追逐、屋顶上轻盈灵动的缠斗，皆以诗意镜头展现武侠的飘逸与禅意。\r\n玉娇龙的叛逆与李慕白的克制形成鲜明对照，前者追求 “要什么就拿什么” 的率性，后者困于 “放不下” 的执念。影片突破传统武侠的正邪对立框架，深入探讨自由与责任、欲望与修行的矛盾。当李慕白因救玉娇龙中剧毒，临终前说出 “我已经浪费了一生”，道尽江湖人的遗憾与顿悟。\r\n李安以细腻的情感刻画和东方美学征服国际影坛，该片斩获奥斯卡最佳外语片等四项大奖，竹林打斗场景成为影史经典。“无论你对此生的决定为何，一定要真诚地对待自己” 的台词，更赋予武侠类型片深刻的哲学内核，使其超越类型边界，成为跨文化共鸣的东方传奇。', 8.4, 1200000, 153110.00, 1, '2025-06-03 19:02:57', 'picture\\\\卧虎藏龙.jpg');
INSERT INTO `movie` VALUES (9, '寄生虫', '기생충', '奉俊昊', '奉俊昊、韩进元', '宋康昊、李善均、崔宇植、朴素丹', '剧情', '韩国', '韩语', '2019-05-30', 132, '贫困的金氏家族通过伪造身份渗透进富豪朴社长家中，两个阶层的碰撞逐渐失控，最终引发血腥冲突。影片以荒诞寓言揭露阶级固化与社会矛盾。贫困的金氏家族通过伪造身份渗透进富豪朴社长家中，两个阶层的碰撞逐渐失控，最终引发血腥冲突。影片以荒诞寓言揭露阶级固化与社会矛盾。', 8.8, 1810000, 79000.00, 1, '2025-06-05 16:36:47', 'picture\\\\寄生虫.jpg');
INSERT INTO `movie` VALUES (10, '绿皮书', 'Green Book', '彼得·法雷里', '尼克·瓦莱隆加、布莱恩·海耶斯·库瑞', '维果·莫腾森、马赫沙拉·阿里', '喜剧', '美国', '英语', '2018-11-21', 130, '1962年，粗鲁的意大利裔司机托尼受雇为黑人钢琴家唐·雪利南下巡演护航，两人在种族歧视严重的南方用幽默与勇气打破偏见，建立跨越种族的友谊。', 8.9, 1470000, 48500.00, 1, '2025-06-05 16:40:36', 'picture\\\\绿皮书.jpg');
INSERT INTO `movie` VALUES (11, '少年的你', '少年的你', '曾国祥', '林咏琛、李媛、许伊萌', '周冬雨、易烊千玺', '剧情', '中国', '汉语普通话', '2019-10-25', 135, '高考前夕，少女陈念遭遇校园霸凌，小混混小北成为她的守护者。一场意外命案让两人卷入犯罪漩涡，在残酷青春中相互救赎。', 8.2, 1780000, 155700.00, 1, '2025-06-05 16:41:39', 'picture\\\\少年的你.jpg');
INSERT INTO `movie` VALUES (12, '何以为家', 'كفرناحوم, Capernaum)\r\nكفرناحوم, Capernaum', '娜丁·拉巴基', '娜丁·拉巴基', '赞恩·阿尔·拉菲亚', '剧情', '黎巴嫩/法国/美国', '阿拉伯语', '2018-05-17', 126, '12岁男孩赞恩因持刀伤人入狱，他起诉父母“生下自己”。影片跟随他流浪街头、照顾黑人婴儿的经历，控诉战争难民儿童的生存困境。', 9.1, 960000, 37400.00, 1, '2025-06-05 16:45:01', 'picture\\\\何以为家.jpg');
INSERT INTO `movie` VALUES (13, '小丑', 'Joker', '托德·菲利普斯', '托德·菲利普斯、斯科特·西尔弗\r\n\r\n', '华金·菲尼克斯', '剧情', '美国', '英语', '2019-10-04', 122, '底层喜剧演员亚瑟·弗莱克在哥谭市遭受社会抛弃与精神崩溃，逐渐蜕变为疯狂反派“小丑”，引发全城暴动。', 8.7, 1230000, 787000.00, 1, '2025-06-05 16:47:00', 'picture\\\\小丑.jpg');
INSERT INTO `movie` VALUES (14, '心灵奇旅', 'Soul', '彼特·道格特', '彼特·道格特、麦克·琼斯', '杰米·福克斯、蒂娜·菲（配音）', '动画', '美国', '英语', '2020-12-25', 101, '中学音乐教师乔伊死后灵魂误入“生之来处”，与厌世灵魂“22”携手返回地球，重新领悟生命真谛。', 8.7, 1120000, 57000.00, 1, '2025-06-05 16:51:11', 'picture\\\\心灵奇旅.jpg');
INSERT INTO `movie` VALUES (15, '1917', '萨姆·门德斯', '萨姆·门德斯', '萨姆·门德斯、克里斯蒂·威尔逊-凯恩斯', '乔治·麦凯、迪恩·查尔斯·查普曼', '剧情', '英国/美国', '英语', '2020-01-10', 119, '一战期间，两名英国士兵穿越德军防线传递撤退命令，一镜到底的沉浸式镜头展现战场生死时速。', 8.5, 760000, 53800.00, 1, '2025-06-05 16:53:09', 'picture\\\\1917.jpg');
INSERT INTO `movie` VALUES (16, '我不是药神', '我不是药神', '文牧野', '韩家女、钟伟、文牧野', '徐峥、王传君、谭卓', '喜剧', '中国', '汉语普通话', '2018-07-05', 117, '印度神油店老板程勇为救病人走私平价抗癌药，从牟利者变为民间英雄，推动中国医药改革。', 9.0, 2100000, 309900.00, 1, '2025-06-05 16:54:34', 'picture\\\\我不是药神.jpg');
INSERT INTO `movie` VALUES (17, '奥本海默', 'Oppenheimer', '克里斯托弗·诺兰', '克里斯托弗·诺兰', '基里安·墨菲、艾米莉·布朗特', '恐怖', '美国/英国', '英语', '2023-08-30', 180, '原子弹之父奥本海默主导曼哈顿计划，却在战后陷入政治迫害，科学与道德的冲突撕裂其人生。', 8.8, 980000, 60000.00, 1, '2025-06-05 16:56:17', 'picture\\\\奥本海默.jpg');
INSERT INTO `movie` VALUES (18, '摔跤吧！爸爸', 'Dangal', '涅提·蒂瓦里', '比于什·古普塔', '阿米尔·汗、萨卡诗·泰瓦', '纪录片', '印度', '印地语', '2017-05-05', 161, '前摔跤冠军马哈维亚训练女儿成为世界级摔跤手，打破印度性别偏见，赢得国家荣誉。', 9.0, 1570000, 129900.00, 1, '2025-06-05 16:58:38', 'picture\\\\摔跤吧！爸爸.jpg');
INSERT INTO `movie` VALUES (19, '疾速追杀', 'John Wick', '大卫·雷奇', '德里克·科尔斯塔', '基努·里维斯', '动作', '美国', '英语', '2014-10-24', 101, '退休杀手因爱犬被杀重出江湖，血洗黑帮复仇。', 7.7, 330000, 88000.00, 1, '2025-06-05 19:18:19', 'picture\\\\疾速追杀.jpg');
